using System.Text;
namespace SurfaceInsight;

public static class Analytics
{
    public static string Correlations(List<Sample> data) { var usable = data.Where(s => !s.Ac && s.Watts > 0).ToList(); if (usable.Count < 8) return "Power correlations need at least eight valid on-battery samples."; var sb = new StringBuilder(); foreach (var app in Insights.Rank(usable).Take(5)) { var xs = usable.Select(s => s.Apps.Where(a => a.Name == app.Name).Sum(a => a.Cpu)).ToArray(); var ys = usable.Select(s => s.Watts!.Value).ToArray(); double mx = xs.Average(), my = ys.Average(); double xx = xs.Sum(x => (x - mx) * (x - mx)), yy = ys.Sum(y => (y - my) * (y - my)); if (xx < 1 || yy < 1) continue; double corr = xs.Zip(ys).Sum(v => (v.First - mx) * (v.Second - my)) / Math.Sqrt(xx * yy); sb.AppendLine($"{app.Name}: CPU/device-draw correlation {corr:F2} across {usable.Count} samples. {(corr > .6 ? "Activity tends to rise with device draw; compare a quiet interval to investigate." : "No strong positive relationship in this interval.")} This is association, with display and other workloads as possible confounders."); } return sb.Length > 0 ? sb.ToString() : "Not enough variation to assess CPU/power relationships yet."; }
    public static string SleepGaps(List<Sample> data) { var sb = new StringBuilder(); for (int i = 1; i < data.Count; i++) { var a = data[i - 1]; var b = data[i]; double hours = (b.Time - a.Time).TotalHours; if (hours < .05 || a.Ac || b.Ac || a.Remaining == null || b.Remaining == null) continue; double loss = (a.Remaining.Value - b.Remaining.Value) / 1000; if (loss < 0) continue; sb.AppendLine($"{a.Time.ToLocalTime():g} → {b.Time.ToLocalTime():g}: {hours:F1} h collection gap, {loss:F2} Wh capacity decrease. The app cannot distinguish sleep from being closed during this gap; confirm with SleepStudy."); } return sb.Length > 0 ? sb.ToString() : "No measurable collection gaps in the selected interval."; }
}
